    meta = c09_final_acceptance_metadata()
    generated = {C09_FINAL_ACCEPTANCE_M, C09_FINAL_ACCEPTANCE_H, C09_FINAL_ACCEPTANCE_P,
                 C09_FINAL_ACCEPTANCE_E, C09_FINAL_ACCEPTANCE_D}
