    pattern = re.escape(fence) + r"json anvil-recovery-summary\s*\{.*?\}\s*" + re.escape(fence)
    handoff_text, count = re.subn(pattern, lambda _: replacement,
                                  historical[C09_FINAL_ACCEPTANCE_H].decode(), flags=re.DOTALL)
