def d03_final_product_raw(root: Path) -> dict[str, dict[str, Any]]:
    result = {}
    for path in d03_final_product_paths():
        raw = (root / path).read_bytes()
        result[path] = {"bytes": len(raw), "sha256": _c21_resume_sha(raw)}
