def c30_r2_historical_tail(root):
    import base64
    import zlib
    raw = zlib.decompress(base64.b64decode(C30_R2_TAIL_B64))
    if _c21_resume_sha(raw) != C30_R2_TAIL_SHA:
        raise ValueError("C30_R2_HISTORY_AUTHORITY_INVALID")
    prior, _ = _c30_history_source(root)
    prefix = raw_event_object_prefix_bytes(prior, 1325) + raw
    if len(prefix) != C30_R2_PREFIX_BYTES or _c21_resume_sha(prefix) != C30_R2_PREFIX_SHA:
        raise ValueError("C30_R2_HISTORY_AUTHORITY_INVALID")
    return {"last_sequence": 1334, "raw_prefix_bytes": C30_R2_PREFIX_BYTES,
            "raw_prefix_sha256": C30_R2_PREFIX_SHA, "raw_tail": raw,
            "events": json.loads(b"[" + raw.lstrip()[1:] + b"]")}


def c30_canonical_paths():
    return sorted([BUNDLE_PATHS[key] for key in ("progress", "events", "handoff_text", "event_contract")]
                  + [C30_CANONICAL_M, C30_CANONICAL_D, C30_CANONICAL_WI, C30_CANONICAL_PROMPT,
                     C30_R2_WI, C30_R2_PROMPT, C30_DEVELOPER_REPORT, C30_SPEC_REPORT, C30_QUALITY_REPORT,
                     "docs/WORK_STATUS.md",
                     "scripts/check_project_progress.py", "tests/tooling/test_project_progress.py"])


def _c30_read_base(root, path):
    return subprocess.check_output(["git", "show", f"{C30_CANONICAL_BASE}:{path}"], cwd=root)


def _c30_history_source(root):
    raw = subprocess.check_output([
        "git", "show", f"{C30_CANONICAL_BASE}:{BUNDLE_PATHS['events']}"
    ], cwd=root)
    prefix = raw_event_object_prefix_bytes(raw, C30_HISTORY_SEQUENCE)
    stream = json.loads(raw)
    if (len(prefix) != C30_HISTORY_BYTES or _c21_resume_sha(prefix) != C30_HISTORY_SHA
            or len(stream["events"]) != C30_HISTORY_SEQUENCE
            or _c21_resume_sha(canonical_json_bytes(stream["events"][1217:])) != C30_CUSTOM_SHA):
        raise ValueError("C30_HISTORY_AUTHORITY_INVALID")
    return raw, stream


def c30_historical_event_profile(root):
    """Return detached, exact profiles, never a reusable event-type allowlist."""
    _, stream = _c30_history_source(root)
    rows = [{"sequence": event["sequence"], "event_id": event["event_id"],
             "event_type": event["event_type"], "actor": event.get("actor"),
             "actor_id": event.get("actor_id"), "subject_ref": event.get("subject_ref"),
             "details_sha256": _c21_resume_sha(canonical_json_bytes(event.get("details"))),
             "event_sha256": _c21_resume_sha(canonical_json_bytes(event))}
            for event in stream["events"][1217:]]
    return {"source_commit": C30_CANONICAL_BASE, "first_sequence": 1218,
            "last_sequence": C30_HISTORY_SEQUENCE, "raw_prefix_bytes": C30_HISTORY_BYTES,
            "raw_prefix_sha256": C30_HISTORY_SHA, "event_array_sha256": C30_CUSTOM_SHA,
            "events": rows}


def validate_c30_historical_events(root, raw, stream):
    try:
        _, frozen = _c30_history_source(root)
        prefix = raw_event_object_prefix_bytes(raw, C30_HISTORY_SEQUENCE)
        if (len(prefix) != C30_HISTORY_BYTES or _c21_resume_sha(prefix) != C30_HISTORY_SHA
                or stream.get("events", [])[:C30_HISTORY_SEQUENCE] != frozen["events"]):
            return ["C30_HISTORY_MUTATED"]
        r2 = c30_r2_historical_tail(root)
        prefix = raw_event_object_prefix_bytes(raw, 1334)
        if (len(prefix) != C30_R2_PREFIX_BYTES or _c21_resume_sha(prefix) != C30_R2_PREFIX_SHA
                or stream.get("events", [])[1325:1334] != r2["events"]):
            return ["C30_HISTORY_MUTATED"]
        return []
    except (ValueError, KeyError, TypeError, OSError, subprocess.CalledProcessError):
        return ["C30_HISTORY_INVALID"]


def _c30_completion(root, completion):
    if completion is None:
        return None
    # Main supplies independently authored evidence after Developer completion.
    # This seam never synthesizes a review or overall C30 acceptance.
    try:
        if type(completion) is not dict or set(completion) != {"developer", "spec", "quality"}:
            raise ValueError
        result = {}
        expected_binding = {
            "base_head": C30_CANONICAL_BASE,
            "checker_sha256": _sha256(root / "scripts/check_project_progress.py"),
            "tests_sha256": _sha256(root / "tests/tooling/test_project_progress.py"),
            "event_sequence": 1340,
            "worker_lease_id": C30_MAIN_WORKER_LEASE,
            "write_lease_id": C30_MAIN_WRITE_LEASE,
            "execution_fencing_token": C30_MAIN_EXECUTION_TOKEN,
            "write_fencing_token": C30_MAIN_WRITE_TOKEN,
        }
        expected_verification = {
            "fresh_tooling_shards": [125, 199, 159, 196],
            "fresh_tooling_passed": 679,
            "focused_passed": 36,
            "focused_deselected": 643,
            "c30_adversarial_passed": 10,
            "compile_exit": 0,
            "live_checker_exit": 0,
            "live_checker_sequence": 1340,
            "diff_check_exit": 0,
        }
        expected_actors = {"developer": C30_MAIN_ACTOR, "spec": "c30_spec_review",
                           "quality": "c30_quality_review"}
        for role in ("developer", "spec", "quality"):
            row = completion[role]
            payload_keys = {"schema_version", "package_id", "role", "actor_id", "verdict", "binding",
                            "verification", "commands", "critical", "important", "minor"}
            if (type(row) is not dict or set(row) != {"path", "sha256", *payload_keys}
                    or any(type(row[k]) is not str for k in ("path", "sha256", "actor_id", "verdict"))
                    or not re.fullmatch(r"docs/(?:04_test_reports|test_reports)/[A-Za-z0-9_./-]+\.md", row["path"])
                    or ".." in row["path"].split("/")
                    or row["schema_version"] != "c30r4_completion_evidence/v1"
                    or row["package_id"] != "C-30R4" or row["role"] != role
                    or row["actor_id"] != expected_actors[role]
                    or row["verdict"] != ("COMPLETED" if role == "developer" else "ACCEPT")
                    or any(type(row[k]) is not int or row[k] != 0 for k in ("critical", "important", "minor"))
                    or type(row["commands"]) is not list or not 1 <= len(row["commands"]) <= 32
                    or any(type(command) is not str or not 1 <= len(command) <= 2048 for command in row["commands"])
                    or not _c21_strict_json_equal(row["binding"], expected_binding)
                    or not _c21_strict_json_equal(row["verification"], expected_verification)
                    or _sha256(root / row["path"]) != row["sha256"]):
                raise ValueError
            text = (root / row["path"]).read_text(encoding="utf-8")
            blocks = re.findall(r"```json c30r4-evidence\r?\n(.*?)\r?\n```", text, flags=re.DOTALL)
            if len(blocks) != 1:
                raise ValueError
            embedded = json.loads(blocks[0])
            if not _c21_strict_json_equal(embedded, {key: row[key] for key in payload_keys}):
                raise ValueError
            result[role] = copy.deepcopy(row)
        if len({row["actor_id"] for row in result.values()}) != 3 or len({row["path"] for row in result.values()}) != 3:
            raise ValueError
        return result
    except (ValueError, TypeError, KeyError, OSError):
        raise ValueError("C30_COMPLETION_EVIDENCE_INVALID") from None


def c30_canonical_projection_from_root(root, *, completion=None):
    """Pure artifact builder. Main alone writes returned controls or accepts."""
    root = Path(root)
    for path, expected in {**C30_CANONICAL_AUTHORITY, **C30_R2_AUTHORITY}.items():
        if _sha256(root / path) != expected:
            raise ValueError("C30_CANONICAL_AUTHORITY_INVALID")
    completion = _c30_completion(root, completion)
    raw_history, history = _c30_history_source(root)
    progress = json.loads(_c30_read_base(root, BUNDLE_PATHS["progress"]))
    contract = json.loads(_c30_read_base(root, BUNDLE_PATHS["event_contract"]))
