def validate_c30_canonical_projection(bundle, manifest):
    try:
        expected = c30_canonical_projection_from_root(bundle["_root"], completion=manifest.get("completion"))
        actual = {BUNDLE_PATHS["progress"]: bundle["progress"], BUNDLE_PATHS["events"]: bundle["events"],
                  BUNDLE_PATHS["event_contract"]: bundle["event_contract"], C30_CANONICAL_D: bundle["detached_digest"],
                  C30_CANONICAL_M: manifest}
        errors = []
        if any(value != json.loads(expected[path]) for path, value in actual.items()):
            errors.append("C30_CANONICAL_PROJECTION_INVALID")
        if bundle["handoff"] != extract_handoff_summary(expected[BUNDLE_PATHS["handoff_text"]].decode()):
            errors.append("C30_CANONICAL_HANDOFF_INVALID")
        if any((bundle["_root"] / path).read_bytes() != raw for path, raw in expected.items()):
            errors.append("C30_CANONICAL_RAW_BINDING_INVALID")
        return sorted(set(errors))
    except (OSError, ValueError, TypeError, KeyError, subprocess.CalledProcessError):
        return ["C30_CANONICAL_INPUT_INVALID"]


def validate_c30_git_facts(*, head, branch, upstream, remote_head, staged, dirty, parent=None, committed=None):
    paths = set(c30_canonical_paths())
    required = {"scripts/check_project_progress.py", "tests/tooling/test_project_progress.py",
                C30_CANONICAL_WI, C30_CANONICAL_PROMPT, C30_R2_WI, C30_R2_PROMPT}
    common = (branch == C09_START_BRANCH and upstream == "development/codex/c09-execution-backends-r1"
              and not staged and len(dirty) == len(set(dirty)))
    precommit = (head == C30_CANONICAL_BASE
                 and remote_head == "98e218264bf54db04a1bd35a67273b713805a649"
                 and required <= set(dirty) <= paths and parent is None and committed is None)
    postcommit = (head != C30_CANONICAL_BASE and parent == C30_CANONICAL_BASE
                  and not dirty and set(committed or []) == paths
                  and len(committed or []) == len(paths)
                  and remote_head in {"98e218264bf54db04a1bd35a67273b713805a649", head})
    valid = common and (precommit or postcommit)
    return [] if valid else ["C30_CANONICAL_GIT_INVALID"]


def _collect_c30_canonical_git(bundle):
    try:
        root = bundle["_root"]
        def names(*args):
            result = _c02_strict_name_only_paths(_c02_git_raw_stdout(root, *args))
            if result is None:
                raise ValueError("C30_GIT_NAMES_UNAVAILABLE")
            return result
        # Staged paths do not depend on ignore policy. Avoid consulting an
        # inaccessible user-global excludes file without editing Git config.
        staged = names("-c", "core.excludesFile=", "diff", "--cached", "--name-only")
        dirty = sorted(set(staged + names("diff", "--name-only") + names("ls-files", "--others",
            "--exclude-per-directory=.gitignore", "--exclude=.pytest_cache", "--exclude=.pytest_cache/**")))
        head = _git_value(root, "rev-parse", "HEAD")
        parent = None
        committed = None
        if head != C30_CANONICAL_BASE:
            parent = _git_value(root, "rev-parse", "HEAD^")
            committed = names("diff", "--name-only", f"{C30_CANONICAL_BASE}..HEAD")
        return validate_c30_git_facts(head=head,
            branch=_git_value(root, "branch", "--show-current"),
            upstream=_git_value(root, "rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}"),
            remote_head=_git_value(root, "rev-parse", "@{u}"), staged=staged, dirty=dirty,
            parent=parent, committed=committed)
    except (OSError, ValueError, subprocess.CalledProcessError):
        return ["C30_CANONICAL_GIT_COLLECTION_FAILED"]


_validate_event_stream_before_c30 = validate_event_stream


def validate_event_stream(stream, contract, progress=None):
    if not isinstance(progress, Mapping) or progress.get("repository", {}).get("projection_mode") != C30_CANONICAL_MODE:
        return _validate_event_stream_before_c30(stream, contract, progress)
    try:
        root = Path(__file__).resolve().parents[1]
        profile = c30_historical_event_profile(root)
        r2 = c30_r2_historical_tail(root)
        profiles = {"C30_SEQ1218_1325": profile, "C30_SEQ1326_1334": {
            "raw_prefix_bytes": C30_R2_PREFIX_BYTES, "raw_prefix_sha256": C30_R2_PREFIX_SHA,
            "event_sha256": [_c21_resume_sha(canonical_json_bytes(row)) for row in r2["events"]]}}
        events = stream["events"]
        if (contract.get("historical_event_profiles") != profiles
                or stream.get("first_sequence") != 1 or stream.get("last_sequence") not in (1340, 1345)
                or len(events) != stream["last_sequence"]
                or stream.get("last_event_id") != events[-1]["event_id"]
                or progress.get("event_sequence") != stream["last_sequence"]):
            return ["C30_EVENT_PROFILE_INVALID"]
        # Existing standard/historical validation remains authoritative before
        # the exact custom profile, rather than filtering any resulting errors.
        prior = {**stream, "events": events[:1217], "last_sequence": 1217,
                 "last_event_id": events[1216]["event_id"]}
        errors = _validate_event_stream_before_c30(prior, contract, None)
        for event, expected in zip(events[1217:1325], profile["events"]):
            if _c21_resume_sha(canonical_json_bytes(event)) != expected["event_sha256"]:
                errors.append("C30_HISTORICAL_EVENT_PROFILE_MISMATCH")
        if events[1325:1334] != r2["events"]:
            errors.append("C30_HISTORICAL_EVENT_PROFILE_MISMATCH")
        expected_types = [row["event_type"] for row in r2["events"]]
        expected_types += ["HUMAN_OVERRIDE_TAKEOVER_RECORDED", "WRITE_LEASE_REVOKED", "WORKER_LEASE_REVOKED", "LEASE_TAKEOVER",
                           "WORKER_LEASE_ISSUED", "WRITE_LEASE_ISSUED"]
        if len(events) == 1345:
            expected_types += ["PACKAGE_COMPLETED", "INDEPENDENT_TEST_JUDGMENT_RECORDED",
                               "WRITE_LEASE_REVOKED", "WORKER_LEASE_REVOKED", "MAIN_PACKAGE_ACCEPTED"]
        if [row["event_type"] for row in events[1325:]] != expected_types:
            errors.append("C30_TAIL_EVENT_ORDER_INVALID")
        previous = _c21_resume_sha(canonical_json_bytes(events[1333]))
        for sequence, row in enumerate(events[1334:], 1335):
            required = contract["payload_contracts"][row["event_type"]]["required_details"]
            if (row["sequence"] != sequence or row.get("previous_event_sha256") != previous
                    or row.get("subject_ref") != "C-30R4" or row.get("actor_id") != C30_MAIN_ACTOR
                    or row.get("actor") != C30_MAIN_ACTOR or any(key not in row["details"] for key in required)):
                errors.append("C30_TAIL_EVENT_CONTRACT_INVALID")
            previous = _c21_resume_sha(canonical_json_bytes(row))
        if progress.get("c30_overall_status") != "PENDING_FINAL_GATE":
            errors.append("C30_PREMATURE_ACCEPTANCE")
        return sorted(set(errors))
    except (ValueError, TypeError, KeyError, IndexError, OSError, subprocess.CalledProcessError):
        return ["C30_EVENT_CONTRACT_INVALID"]


